require_once __DIR__.'/includes/auth.php';require_login();$uid=current_user_id();$errors=[];$st=$pdo->prepare('SELECT full_name,username,email,profile_photo FROM users WHERE user_id=?');$st->execute([$uid]);$user=$st->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['full_name']??''));$username=strtolower(trim((string)($_POST['username']??'')));if(mb_strlen($name)<2||mb_strlen($name)>100)$errors[]='Name must be 2–100 characters.';if(!preg_match('/^[a-z0-9_]{3,40}$/',$username))$errors[]='Username must be 3–40 letters, numbers or underscores.';$st=$pdo->prepare('SELECT user_id FROM users WHERE (username=? OR email=?) AND user_id<>?');$st->execute([$username,$user['email'],$uid]);if($st->fetch())$errors[]='Username is already taken.';$photo=$user['profile_photo'];if(!empty($_FILES['profile_photo']['name'])&&$_FILES['profile_photo']['error']===UPLOAD_ERR_OK){if($_FILES['profile_photo']['size']>3*1024*1024)$errors[]='Profile photo must be under 3 MB.';else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['profile_photo']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)$errors[]='Profile photo must be JPG, PNG or WEBP.';else{$fn='avatar_'.bin2hex(random_bytes(12)).'.'.$ext;$dir=__DIR__.'/uploads/avatars';if(!is_dir($dir))mkdir($dir,0755,true);if(move_uploaded_file($_FILES['profile_photo']['tmp_name'],$dir.'/'.$fn))$photo='uploads/avatars/'.$fn;else $errors[]='Could not upload profile photo.';}}}if(!$errors){$st=$pdo->prepare('UPDATE users SET full_name=?,username=?,profile_photo=? WHERE user_id=?');$st->execute([$name,$username,$photo,$uid]);$_SESSION['full_name']=$name;$_SESSION['username']=$username;$_SESSION['profile_photo']=$photo;if(!empty($_POST['new_password'])){if(strlen((string)($_POST['new_password']))<8)$errors[]='New password must be at least 8 characters.';else $pdo->prepare('UPDATE users SET password_hash=? WHERE user_id=?')->execute([password_hash((string)$_POS