<section class="standalone-panel"><a class="back-link" href="dashboard.php">← Back to messages</a><div class="eyebrow">YOUR ACCOUNT</div><h1>Profile settings</h1><p class="muted">Update how other people see you on ChatApp.</p><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Profile updated successfully.</div><?php endif; ?><?php foreach($errors as $er): ?><div class="alert alert-error"><?= e($er) ?></div><?php endforeach; ?><form method="post" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Profile photo<input type="file" name="profile_photo" accept="image/png,image/jpeg,image/webp"><small>JPG, PNG or WEBP · up to 3 MB.</small></label><?php if($user['profile_photo']): ?><img class="profile-preview" src="<?= e($user['profile_photo']) ?>" alt="Current profile photo"><?php endif; ?><label>Full name<input name="full_name" value="<?= e($user['full_name']) ?>" required maxlength="100"></label><label>Username<input name="username" value="<?= e($user['username']) ?>" required maxlength="40"></label><label>Email<input value="<?= e($user['email']) ?>" disabled><small>Email address cannot be changed here.</small></label><label>New password (optional)<input type="password" name="new_password" minlength="8" autocomplete="new-password" placeholder="Leave blank to keep current password"></label><button class="button button-primary" type="submit">Save profile</button></form></section><?php require __DIR__.'/includes/footer.php';?>
